set-variable.value:
@{
      try {
          var body = context.Request.Body?.As<JObject>(true);
          if (body == null) { return string.Empty; }
          var model = body["model"];
          if (model == null) { return string.Empty; }
          var alias = model.ToString();
          // Bound the echo length: this value is attacker-controlled and is reflected
          // back in the 403 body.
          return alias.Length > 128 ? alias.Substring(0, 128) : alias;
      } catch (Exception) {
          return string.Empty;
      }
  }

@{
      var alias = (string)context.Variables["fgAlias"];
      if (string.IsNullOrEmpty(alias)) { return string.Empty; }
      try {
          var raw = context.Variables.ContainsKey("fgModelMap")
              ? (string)context.Variables["fgModelMap"]
              : string.Empty;
          if (string.IsNullOrWhiteSpace(raw)) { return string.Empty; }
          var entry = JObject.Parse(raw)[alias] as JObject;
          if (entry == null) { return string.Empty; }
          if (entry["deployment"] == null || entry["backend"] == null || entry["provider"] == null) {
              return string.Empty;
          }
          return entry.ToString(Newtonsoft.Json.Formatting.None);
      } catch (Exception) {
          return string.Empty;
      }
  }

@{
      var alias = (string)context.Variables["fgAlias"];
      if (string.IsNullOrEmpty(alias)) { return string.Empty; }
      var raw = (string)context.Variables["fgAliasEntry"];
      if (string.IsNullOrEmpty(raw)) {
          return "Model '" + alias + "' is not available on your FoundryGate plan.";
      }
      var provider = (string)JObject.Parse(raw)["provider"];
      if (provider != (string)context.Variables["fgApiProvider"]) {
          var path = provider == "anthropic" ? "__ANTHROPIC_API_PATH__" : "__OPENAI_API_PATH__";
          return "Model '" + alias + "' is served by the " + provider
              + " front door on this gateway. Send this request to /" + path + " instead.";
      }
      return string.Empty;
  }

return-response.set-body:
@{
            var message = (string)context.Variables["fgDenyMessage"];
            if (context.Api.Id == "__ANTHROPIC_API_ID__") {
                return new JObject(
                    new JProperty("type", "error"),
                    new JProperty("error", new JObject(
                        new JProperty("type", "permission_error"),
                        new JProperty("message", message)))
                ).ToString(Newtonsoft.Json.Formatting.None);
            }
            return new JObject(
                new JProperty("error", new JObject(
                    new JProperty("code", "model_not_permitted"),
                    new JProperty("type", "invalid_request_error"),
                    new JProperty("param", "model"),
                    new JProperty("message", message)))
            ).ToString(Newtonsoft.Json.Formatting.None);
        }

when.set-body:
@{
          var entry = JObject.Parse((string)context.Variables["fgAliasEntry"]);
          var body = context.Request.Body.As<JObject>(true);
          body["model"] = (string)entry["deployment"];
          return body.ToString(Newtonsoft.Json.Formatting.None);
      }
